                        raise ValueError("Unterminated string")
                    if s[i] == 'n':
                        s = s[:i] + '\n' + s[i+1:]
                    elif s[i] == 'r':
                        s = s[:i] + '\r' + s[i+1:]
                    elif s[i] == 't':
                        s = s[:i] + '\t' + s[i+1:]
