                        s = s[:i] + '\b' + s[i+1:]
                    elif s[i] == 'f':
                        s = s[:i] + '\f' + s[i+1:]
                    elif s[i] == 'u':
                        i += 1
                        if i + 4 > len(s):
                            raise ValueError("Invalid Unicode escape sequence")
